<?php
require_once __DIR__.'/auth.php'; require_admin(); $pdo=db(); if(!$pdo){header('Location: products.php?error=Chưa kết nối được MySQL');exit;}
$fields=['name','slug','description','price','rating','reviews','status','category_id','collection_id'];foreach($fields as $f)if(!isset($_POST[$f])){header('Location: products.php?error=Dữ liệu không hợp lệ');exit;}$data=[];foreach($fields as $f)$data[$f]=trim((string)$_POST[$f]);$data['video_url']=trim((string)($_POST['video_url']??''));$data['category_id']=(int)$data['category_id'];$data['collection_id']=(int)$data['collection_id'];
$data['detailed_description']=(string)($_POST['detailed_description']??'');
$specLabels=$_POST['spec_label']??[];$specValues=$_POST['spec_value']??[];$specs=[];foreach($specLabels as $i=>$label){$label=trim((string)$label);$value=trim((string)($specValues[$i]??''));if($label!==''||$value!=='')$specs[]=['label'=>$label,'value'=>$value];}$data['specifications_json']=json_encode($specs,JSON_UNESCAPED_UNICODE);
if(!preg_match('/^[a-z0-9-]+$/',$data['slug'])||$data['name']===''||!$data['category_id']||!$data['collection_id']||($data['video_url']!==''&&!filter_var($data['video_url'],FILTER_VALIDATE_URL))){header('Location: product-form.php?error=Vui lòng kiểm tra lại thông tin'.(!empty($_POST['id'])?'&id='.(int)$_POST['id']:''));exit;}$cat=$pdo->prepare('SELECT name FROM categories WHERE id=?');$cat->execute([$data['category_id']]);$data['type']=$cat->fetchColumn();if(!$data['type']){header('Location: product-form.php?error=Danh mục không tồn tại');exit;}$data['fast']=isset($_POST['fast'])?1:0;$data['active']=isset($_POST['active'])?1:0;$data['featured']=isset($_POST['featured'])?1:0;
function upload_product_images(): array {$out=[];$files=$_FILES['uploaded_images']??null;if(!$files)return $out;$dir=__DIR__.'/../uploads/products';if(!is_dir($dir)&&!mkdir($dir,0755,true))return $out;$ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$finfo=new finfo(FILEINFO_MIME_TYPE);foreach((array)$files['tmp_name'] as $i=>$tmp){if(($files['error'][$i]??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;if(($files['error'][$i]??0)!==UPLOAD_ERR_OK||($files['size'][$i]??0)>10485760||!is_uploaded_file($tmp))continue;$mime=$finfo->file($tmp);if(!isset($ok[$mime]))continue;$name=bin2hex(random_bytes(16)).'.'.$ok[$mime];if(move_uploaded_file($tmp,$dir.'/'.$name))$out[]='/uploads/products/'.$name;}return $out;}
try{$pdo->beginTransaction();if(!empty($_POST['id'])){$id=(int)$_POST['id'];$data['id']=$id;$pdo->prepare('UPDATE products SET name=:name,slug=:slug,type=:type,category_id=:category_id,collection_id=:collection_id,description=:description,detailed_description=:detailed_description,specifications_json=:specifications_json,price=:price,rating=:rating,reviews=:reviews,video_url=:video_url,status=:status,fast=:fast,active=:active,featured=:featured WHERE id=:id')->execute($data);$msg='Đã lưu thay đổi';}else{$pdo->prepare('INSERT INTO products(name,slug,type,category_id,collection_id,description,detailed_description,specifications_json,price,rating,reviews,image,video_url,status,fast,active,featured) VALUES(:name,:slug,:type,:category_id,:collection_id,:description,:detailed_description,:specifications_json,:price,:rating,:reviews,"",:video_url,:status,:fast,:active,:featured)')->execute($data);$id=(int)$pdo->lastInsertId();$msg='Đã tạo sản phẩm mới';}$uploads=upload_product_images();if($uploads){$sort=(int)$pdo->query('SELECT COALESCE(MAX(sort_order),0) FROM product_images WHERE product_id='.$id)->fetchColumn();$ins=$pdo->prepare('INSERT INTO product_images(product_id,image_url,is_featured,sort_order) VALUES(?,?,0,?)');foreach($uploads as $url)$ins->execute([$id,$url,++$sort]);}$selected=trim((string)($_POST['featured_image']??''));if($selected===''&&!empty($uploads))$selected=$uploads[0];if($selected!==''){$v=$pdo->prepare('SELECT COUNT(*) FROM product_images WHERE product_id=? AND image_url=?');$v->execute([$id,$selected]);if($v->fetchColumn()){$pdo->prepare('UPDATE product_images SET is_featured=0 WHERE product_id=?')->execute([$id]);$pdo->prepare('UPDATE product_images SET is_featured=1 WHERE product_id=? AND image_url=?')->execute([$id,$selected]);$pdo->prepare('UPDATE products SET image=? WHERE id=?')->execute([$selected,$id]);}}$pdo->commit();header('Location: products.php?ok='.urlencode($msg));}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();header('Location: product-form.php?error='.urlencode('Không thể lưu sản phẩm').(!empty($_POST['id'])?'&id='.(int)$_POST['id']:''));}
